# =============================================================================
# KRB — JOURNAL FIGURE GENERATOR FOR FIVE-EVENT VGAE LOBO VALIDATION
# Generates six figure groups for both flood-fraction targets (>=1%, >=5%).
#
# INPUTS generated by:
# KRB_VGAE_ONLY_FIVE_EVENT_LOBO_VALIDATION_1PCT_5PCT.py
#
# Required CSVs:
#   VGAE_LOBO_Basin_Event_Scores.csv
#   VGAE_Cluster_Flood_Fractions.csv
#
# Spatial input:
#   VGAE_FSM_5CLASS.gpkg, layer vgae_fsm_5class
#
# Important:
# - ROC/PR curves use continuous LOBO scores.
# - Confusion matrices and spatial error classes use the event-wise median
#   LOBO score threshold, matching the validation script.
# - This is retrospective same-event peer-cluster association, not prospective
#   independent prediction.
# =============================================================================

from pathlib import Path
import warnings
import numpy as np
import pandas as pd
import geopandas as gpd
import matplotlib.pyplot as plt

from sklearn.metrics import (
    roc_curve, precision_recall_curve, roc_auc_score,
    average_precision_score, confusion_matrix
)

warnings.filterwarnings("ignore", category=UserWarning)

# ------------------------------- PATHS ---------------------------------------
BASE_DIR = Path(
    r"D:\KRB_FINAL_GRAPH_PROJECT_V6\FSM_UNSUPERVISED"
    r"\VGAE_ONLY_FIVE_EVENT_LOBO_VALIDATION"
)
BASIN_CSV = BASE_DIR / "VGAE_LOBO_Basin_Event_Scores.csv"
CLUSTER_CSV = BASE_DIR / "VGAE_Cluster_Flood_Fractions.csv"

GPKG = Path(
    r"D:\KRB_FINAL_GRAPH_PROJECT_V6\FSM_UNSUPERVISED"
    r"\KRB_FINAL_VGAE_DINKNET_FSM_REGIONALIZATION_LAYERS"
    r"\VGAE_FSM_5CLASS.gpkg"
)
GPKG_LAYER = "vgae_fsm_5class"
NODE_FIELD = "node_index"
CLUSTER_FIELD = "VGAE_FSM_cluster10"

OUT = BASE_DIR / "JOURNAL_FIGURES_6_GROUPS"
EVENTS = ["2020", "2021", "2022", "2023", "2024"]
TARGETS = {
    "1pct": ("Target_flood_fraction_ge_1pct", "Flood fraction ≥1%"),
    "5pct": ("Target_flood_fraction_ge_5pct", "Flood fraction ≥5%"),
}

DPI = 600


def check_inputs():
    for p in [BASIN_CSV, CLUSTER_CSV, GPKG]:
        if not p.exists():
            raise FileNotFoundError(
                f"Required input not found: {p}\n"
                "Run the five-event LOBO validation script first and check paths."
            )


def load_inputs():
    basin = pd.read_csv(BASIN_CSV)
    cluster = pd.read_csv(CLUSTER_CSV, dtype={"Event": str})
    basin["Event"] = basin["Event"].astype(str)
    cluster["Event"] = cluster["Event"].astype(str)

    required_basin = {
        "Event", "node_index", "Cluster_ID", "Flood_fraction",
        "LOBO_cluster_flood_score",
        "Target_flood_fraction_ge_1pct",
        "Target_flood_fraction_ge_5pct",
    }
    missing = required_basin - set(basin.columns)
    if missing:
        raise ValueError(f"Basin CSV is missing fields: {sorted(missing)}")

    required_cluster = {
        "Event", "Cluster_ID", "Pixel_weighted_flood_fraction_percent"
    }
    missing = required_cluster - set(cluster.columns)
    if missing:
        raise ValueError(f"Cluster CSV is missing fields: {sorted(missing)}")

    basin = basin[basin["Event"].isin(EVENTS)].copy()
    cluster = cluster[cluster["Event"].isin(EVENTS)].copy()

    if basin.duplicated(["Event", "node_index"]).any():
        raise ValueError("Duplicate Event + node_index rows in basin CSV.")
    return basin, cluster


def savefig(fig, name):
    path = OUT / name
    fig.savefig(path, dpi=DPI, bbox_inches="tight")
    plt.close(fig)
    print("Saved:", path)


# FIGURE 1 — ROC and Precision–Recall curves (2 targets x 2 curve types).
def figure_1_curves(basin):
    fig, axes = plt.subplots(2, 2, figsize=(13, 10))
    for r, (key, (target_col, target_label)) in enumerate(TARGETS.items()):
        for event in EVENTS:
            d = basin[basin["Event"] == event].dropna(
                subset=[target_col, "LOBO_cluster_flood_score"]
            )
            y = d[target_col].astype(int).to_numpy()
            s = d["LOBO_cluster_flood_score"].astype(float).to_numpy()
            if len(np.unique(y)) < 2:
                continue

            fpr, tpr, _ = roc_curve(y, s)
            auc = roc_auc_score(y, s)
            axes[r, 0].plot(fpr, tpr, label=f"{event} (AUC={auc:.3f})")

            precision, recall, _ = precision_recall_curve(y, s)
            ap = average_precision_score(y, s)
            axes[r, 1].plot(recall, precision, label=f"{event} (AP={ap:.3f})")

        axes[r, 0].plot([0, 1], [0, 1], linestyle="--")
        axes[r, 0].set_title(f"{target_label}: ROC")
        axes[r, 0].set_xlabel("False-positive rate")
        axes[r, 0].set_ylabel("True-positive rate")
        axes[r, 0].set_xlim(0, 1)
        axes[r, 0].set_ylim(0, 1)
        axes[r, 0].legend(frameon=False, fontsize=8)

        # AP baseline is the positive prevalence; show event-specific baselines.
        for event in EVENTS:
            d = basin[basin["Event"] == event].dropna(subset=[target_col])
            if len(d):
                prevalence = d[target_col].astype(int).mean()
                axes[r, 1].axhline(
                    prevalence, linestyle=":", linewidth=0.8
                )
        axes[r, 1].set_title(f"{target_label}: Precision–Recall")
        axes[r, 1].set_xlabel("Recall")
        axes[r, 1].set_ylabel("Precision")
        axes[r, 1].set_xlim(0, 1)
        axes[r, 1].set_ylim(0, 1)
        axes[r, 1].legend(frameon=False, fontsize=8)

    fig.suptitle(
        "Five-event VGAE LOBO discrimination performance", fontsize=14
    )
    fig.tight_layout()
    savefig(fig, "Figure_1_ROC_and_Precision_Recall_Curves.png")


# FIGURE 2 — Confusion matrices at median score threshold.
def figure_2_confusion(basin):
    fig, axes = plt.subplots(2, 5, figsize=(16, 7))
    for r, (key, (target_col, target_label)) in enumerate(TARGETS.items()):
        for c, event in enumerate(EVENTS):
            ax = axes[r, c]
            d = basin[basin["Event"] == event].dropna(
                subset=[target_col, "LOBO_cluster_flood_score"]
            )
            y = d[target_col].astype(int).to_numpy()
            s = d["LOBO_cluster_flood_score"].astype(float).to_numpy()
            threshold = float(np.median(s))
            pred = (s >= threshold).astype(int)
            cm = confusion_matrix(y, pred, labels=[0, 1])
            ax.imshow(cm)
            ax.set_title(f"{event} | {key}")
            ax.set_xticks([0, 1], ["Non-flood", "Flood"], rotation=25)
            ax.set_yticks([0, 1], ["Non-flood", "Flood"])
            ax.set_xlabel("Predicted")
            if c == 0:
                ax.set_ylabel(f"{target_label}\nObserved")
            names = [["TN", "FP"], ["FN", "TP"]]
            for i in range(2):
                for j in range(2):
                    ax.text(
                        j, i, f"{names[i][j]}\n{cm[i, j]}",
                        ha="center", va="center"
                    )
    fig.suptitle(
        "Confusion matrices using event-wise median LOBO score thresholds",
        fontsize=14
    )
    fig.tight_layout()
    savefig(fig, "Figure_2_Confusion_Matrices_1pct_5pct.png")


# FIGURE 3 — Distribution of continuous LOBO scores by observed class.
def figure_3_score_distributions(basin):
    fig, axes = plt.subplots(2, 5, figsize=(16, 7), sharey="row")
    for r, (key, (target_col, target_label)) in enumerate(TARGETS.items()):
        for c, event in enumerate(EVENTS):
            ax = axes[r, c]
            d = basin[basin["Event"] == event].dropna(
                subset=[target_col, "LOBO_cluster_flood_score"]
            )
            groups = [
                d.loc[d[target_col].astype(int) == cls,
                      "LOBO_cluster_flood_score"].to_numpy()
                for cls in [0, 1]
            ]
            # Matplotlib >= 3.9 renamed `labels` to `tick_labels`.
            # Fall back to the older argument for older Matplotlib releases.
            if len(groups[0]) == 0 or len(groups[1]) == 0:
                ax.text(
                    0.5, 0.5, "One class has no observations",
                    ha="center", va="center", transform=ax.transAxes
                )
                ax.set_xticks([1, 2], ["Negative", "Positive"])
            else:
                try:
                    ax.boxplot(
                        groups,
                        tick_labels=["Negative", "Positive"],
                        showfliers=False
                    )
                except TypeError:
                    ax.boxplot(
                        groups,
                        labels=["Negative", "Positive"],
                        showfliers=False
                    )
            ax.set_title(event)
            ax.tick_params(axis="x", labelrotation=25)
            if c == 0:
                ax.set_ylabel(f"{target_label}\nLOBO score")
    fig.suptitle(
        "Distribution of continuous LOBO scores by observed flood class",
        fontsize=14
    )
    fig.tight_layout()
    savefig(fig, "Figure_3_LOBO_Score_Distributions.png")


# FIGURE 4 — Cluster x event pixel-weighted observed flood fraction.
def figure_4_cluster_heatmap(cluster):
    pivot = cluster.pivot(
        index="Cluster_ID",
        columns="Event",
        values="Pixel_weighted_flood_fraction_percent"
    ).reindex(index=sorted(cluster["Cluster_ID"].unique()), columns=EVENTS)
    fig, ax = plt.subplots(figsize=(8, 7))
    im = ax.imshow(pivot.to_numpy(), aspect="auto")
    ax.set_xticks(range(len(EVENTS)), EVENTS)
    ax.set_yticks(range(len(pivot.index)), [f"Cluster {x}" for x in pivot.index])
    ax.set_xlabel("Flood event")
    ax.set_ylabel("Original VGAE K=10 cluster")
    ax.set_title("Pixel-weighted observed flood fraction by cluster (%)")
    fig.colorbar(im, ax=ax, label="Flood fraction (%)")
    for i in range(pivot.shape[0]):
        for j in range(pivot.shape[1]):
            v = pivot.iloc[i, j]
            if pd.notna(v):
                ax.text(j, i, f"{v:.1f}", ha="center", va="center", fontsize=8)
    fig.tight_layout()
    savefig(fig, "Figure_4_Cluster_Event_Flood_Fraction_Heatmap.png")


# FIGURE 5 — Spatial error maps, ten panels (five events x two targets).
def figure_5_spatial_errors(basin):
    gdf = gpd.read_file(GPKG, layer=GPKG_LAYER)
    if NODE_FIELD not in gdf.columns or CLUSTER_FIELD not in gdf.columns:
        raise ValueError(
            f"GeoPackage layer must contain {NODE_FIELD} and {CLUSTER_FIELD}."
        )
    gdf[NODE_FIELD] = pd.to_numeric(gdf[NODE_FIELD]).astype(int)
    if gdf[NODE_FIELD].duplicated().any():
        raise ValueError("Duplicate node_index values in GeoPackage.")
    if len(gdf) != 508:
        raise ValueError(f"Expected 508 polygons; found {len(gdf)}.")

    # Project to a metric CRS for consistent basin mapping.
    if gdf.crs is None:
        raise ValueError("GeoPackage has no CRS.")
    gdf = gdf.to_crs(gdf.estimate_utm_crs())

    fig, axes = plt.subplots(2, 5, figsize=(16, 9))
    for r, (key, (target_col, target_label)) in enumerate(TARGETS.items()):
        for c, event in enumerate(EVENTS):
            d = basin[basin["Event"] == event].dropna(
                subset=[target_col, "LOBO_cluster_flood_score"]
            ).copy()
            threshold = float(d["LOBO_cluster_flood_score"].median())
            d["Predicted"] = (
                d["LOBO_cluster_flood_score"].astype(float) >= threshold
            ).astype(int)
            d["Observed"] = d[target_col].astype(int)
            d["Error_class"] = np.select(
                [
                    (d["Observed"] == 1) & (d["Predicted"] == 1),
                    (d["Observed"] == 0) & (d["Predicted"] == 0),
                    (d["Observed"] == 0) & (d["Predicted"] == 1),
                    (d["Observed"] == 1) & (d["Predicted"] == 0),
                ],
                ["TP", "TN", "FP", "FN"],
                default="No data"
            )
            merged = gdf.merge(
                d[[NODE_FIELD, "Error_class"]],
                left_on=NODE_FIELD, right_on=NODE_FIELD, how="left",
                validate="one_to_one"
            )
            ax = axes[r, c]
            merged.plot(
                column="Error_class", categorical=True, legend=(r == 0 and c == 4),
                ax=ax, missing_kwds={"color": "lightgrey", "label": "No data"},
                linewidth=0.05, edgecolor="grey"
            )
            ax.set_title(f"{event} | {key}")
            ax.set_axis_off()
            if c == 0:
                ax.text(
                    0.02, 0.02, target_label, transform=ax.transAxes,
                    fontsize=8, va="bottom"
                )
    fig.suptitle(
        "Spatial distribution of LOBO classification outcomes",
        fontsize=14
    )
    fig.tight_layout()
    savefig(fig, "Figure_5_Spatial_Error_Maps.png")


# FIGURE 6 — Inter-event correlation of basin-level LOBO scores.
def figure_6_inter_event_correlation(basin):
    fig, axes = plt.subplots(1, 2, figsize=(11, 5))
    for ax, (key, _) in zip(axes, TARGETS.items()):
        pivot = basin.pivot(
            index="node_index",
            columns="Event",
            values="LOBO_cluster_flood_score"
        ).reindex(columns=EVENTS)
        corr = pivot.corr(method="pearson", min_periods=20)
        im = ax.imshow(corr.to_numpy(), vmin=-1, vmax=1)
        ax.set_xticks(range(5), EVENTS)
        ax.set_yticks(range(5), EVENTS)
        ax.set_title(f"LOBO score correlation | {key}")
        ax.set_xlabel("Flood event")
        ax.set_ylabel("Flood event")
        for i in range(5):
            for j in range(5):
                v = corr.iloc[i, j]
                ax.text(j, i, f"{v:.2f}", ha="center", va="center", fontsize=8)
        fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04, label="Pearson r")
        corr.to_csv(OUT / f"Figure_6_Basin_LOBO_Score_Correlation_{key}.csv")
    fig.suptitle("Inter-event consistency of basin-level LOBO scores", fontsize=14)
    fig.tight_layout()
    savefig(fig, "Figure_6_Inter_Event_Basin_LOBO_Correlation.png")


def main():
    check_inputs()
    OUT.mkdir(parents=True, exist_ok=True)
    basin, cluster = load_inputs()

    # Save a compact data audit.
    audit = basin.groupby("Event").agg(
        N_basins=("node_index", "nunique"),
        Mean_LOBO_score=("LOBO_cluster_flood_score", "mean"),
        Median_LOBO_score=("LOBO_cluster_flood_score", "median"),
        Mean_flood_fraction=("Flood_fraction", "mean"),
    )
    audit.to_csv(OUT / "Input_Data_Audit.csv")

    figure_1_curves(basin)
    figure_2_confusion(basin)
    figure_3_score_distributions(basin)
    figure_4_cluster_heatmap(cluster)
    figure_5_spatial_errors(basin)
    figure_6_inter_event_correlation(basin)

    print("\nAll six figure groups have been generated.")
    print("Output folder:", OUT)
    print(
        "Check figure captions and the methodological note: confusion and "
        "spatial error classes use event-wise median LOBO scores."
    )


if __name__ == "__main__":
    main()
